SELECT a FROM t AS OF TIMESTAMP SYSTIMESTAMP - INTERVAL '1' HOUR;

SELECT a FROM t AS OF SCN 1000;

SELECT a FROM t AS OF TIMESTAMP TO_TIMESTAMP('2020-01-01 00:00:00', 'YYYY-MM-DD HH24:MI:SS');

SELECT a FROM employees AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL '1' HOUR);

SELECT a FROM t AS OF SCN 1000 e;

SELECT e.a FROM t AS OF TIMESTAMP SYSTIMESTAMP e JOIN u ON e.id = u.id;
